// Guardrail Ebene 2: gültige Kundenkennung, gültige paket_id, die zu diesem Auftrag gehört, Hinweis auf 300 Zeichen begrenzt. Die Kundenkennung setzt der Hauptworkflow fest.
const j = $input.first().json;
const kuerzel = String(j.kuerzel ?? '').trim().toLowerCase();
const paketId = String(j.paket_id ?? '').trim();
const trace = String(j.trace_id ?? '').trim().slice(0, 60) || 'ohne_trace_id';
const hinweis = String(j.hinweis_an_mensch ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
let fehler = '';
if (!/^[a-z0-9-]{2,40}$/.test(kuerzel)) fehler = 'FEHLER: ungültige Kundenkennung, nichts eingereicht.';
else if (!/^paket-[A-Za-z0-9_-]{3,100}$/.test(paketId)) fehler = 'FEHLER: paket_id fehlt oder ist ungültig, nichts eingereicht. Rufe zuerst Text_schreiben auf und nutze die paket_id aus dessen Antwort.';
else if (trace !== 'ohne_trace_id' && !paketId.startsWith('paket-' + trace + '-')) fehler = 'FEHLER: Diese paket_id gehört nicht zu diesem Auftrag, nichts eingereicht.';
return [{ json: { kuerzel: kuerzel, paket_id: paketId, trace_id: trace, hinweis: hinweis, eingabe_ok: fehler === '', fehler_text: fehler } }];

// Zweck (Werkzeug 5): aus dem gespeicherten Paket (k2_pakete) und den Bildern daraus genau eine Beitragszeile bauen. Status immer wartet_auf_freigabe, veröffentlicht wird nichts.
// Warum Doppelschutz: je Auftrag (trace_id) höchstens 1 Beitrag von p2_agent, sonst gäbe es zwei Freigaben für denselben Lauf.
const e = $('Eingabe prüfen [Code]').first().json;
const pRow = $('Paket lesen [Supabase]').first().json || {};
const kunde = $('Kunde lesen [Supabase]').first().json || {};
const vorh = $input.first().json || {};
const stopp = t => [{ json: { bereit: false, fehler_text: t } }];
if (!pRow.paket_id) return stopp('NICHT_GEFUNDEN: Für diese paket_id liegt kein Paket vor, nichts eingereicht.');
if (pRow.paket_id !== e.paket_id || pRow.kuerzel !== e.kuerzel) return stopp('FEHLER: Das Paket gehört nicht zu diesem Kunden, nichts eingereicht.');
if (!kunde.id || kunde.kuerzel !== e.kuerzel) return stopp('NICHT_GEFUNDEN: Für diesen Kunden gibt es kein aktives Profil, nichts eingereicht.');
if (e.trace_id !== 'ohne_trace_id' && vorh.id) return stopp('FEHLER: Für diesen Auftrag wurde schon ein Beitrag eingereicht, nichts erneut eingereicht.');
let paket = pRow.paket;
if (typeof paket === 'string') { try { paket = JSON.parse(paket); } catch (x) { return stopp('FEHLER: Das gespeicherte Paket ist nicht lesbar, nichts eingereicht.'); } }
const slides = paket && Array.isArray(paket.slides) ? paket.slides : [];
if (slides.length < 5 || slides.length > 8 || !String(paket.caption_instagram || '').trim() || !String(paket.linkedin_post || '').trim()) return stopp('FEHLER: Das Paket ist unvollständig (Folien, Instagram-Text oder LinkedIn-Post fehlen), nichts eingereicht.');
let pfade = [];
let bilderHinweis = 'ohne Bilder';
if (pRow.bilder && typeof pRow.bilder === 'object') {
  pfade = Array.isArray(pRow.bilder.pfade) ? pRow.bilder.pfade.map(String) : [];
  const vorn = e.kuerzel + '/' + e.paket_id + '/';
  if (pfade.some(p => !p.startsWith(vorn) || p.includes('..'))) return stopp('FEHLER: Die Bildpfade gehören nicht zu diesem Paket, nichts eingereicht.');
  bilderHinweis = 'mit Bildern (' + String(pRow.bilder.quelle || 'unbekannt') + (pRow.bilder.ki_bild ? ', KI-Bild' : '') + ')';
}
const folien = pfade.filter(p => /\/folie-\d\d\.png$/.test(p)).sort();
const einzel = pfade.find(p => p.endsWith('/einzelbild.png')) || '';
if (pfade.length && folien.length !== slides.length) return stopp('FEHLER: Anzahl der Folienbilder passt nicht zu den Folien, nichts eingereicht.');
const tags = Array.isArray(paket.hashtags) ? paket.hashtags.map(String).slice(0, 10) : [];
const post = { customer_id: kunde.id, source_type: 'Thema', source: 'Redaktions-Agent', topic: String(slides[0].heading || '').slice(0, 200),
  execution_id: e.trace_id, status: 'wartet_auf_freigabe', erzeugt_von: 'p2_agent', ai_generated: true,
  slides: slides.map((s, i) => ({ index: i + 1, type: s.type, heading: s.heading, text: s.text, image_path: folien[i] || null })),
  slide_urls: folien, single_image_url: einzel || null,
  caption_instagram: String(paket.caption_instagram), linkedin_post: String(paket.linkedin_post), hashtags: tags, model: String(pRow.modell || 'unbekannt').slice(0, 120) };
return [{ json: { bereit: true, post: post, bilder_anzahl: pfade.length, bilder_hinweis: bilderHinweis, hinweis: e.hinweis } }];

// Rückgabe an den Agenten: post_id nur aus der Antwort der Datenbank, kein Erfolg ohne gespeicherte Zeile.
const b = $('Beitrag bauen [Code]').first().json;
const row = $input.first().json || {};
if (!row.id || row.status !== 'wartet_auf_freigabe' || row.erzeugt_von !== 'p2_agent') throw new Error('Einreichen: Beitrag nicht bestätigt.');
const zeilen = ['STATUS: OK', 'post_id: ' + row.id, 'status: wartet_auf_freigabe', 'bilder: ' + b.bilder_anzahl + ' (' + b.bilder_hinweis + ')'];
if (b.hinweis) zeilen.push('hinweis_an_mensch: ' + b.hinweis);
zeilen.push('Der Beitrag wartet auf die Freigabe durch einen Menschen. Veröffentlicht oder abgelegt ist nichts. Rufe dieses Werkzeug nicht erneut auf.');
return [{ json: { antwort: zeilen.join('\n'), post_id: row.id, status: row.status } }];
